-- The SPADE-CHAM code key (Code keys -> Drilling -> SPADE-CHAM), from the ISCAR
-- e-catalog's SPADE-CHAM families; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.spadecham', $ck${"title": "SPADE-CHAM code key – drilling heads and drill bodies", "subtitle": "Large diameter (33 – 40 mm) self-locking exchangeable heads (HFP, IFP, IFHP) and the DFN drill bodies that carry them", "example": "HFP 330-SPADE IQ", "decoder": "spade-cham", "sections": [{"key": "i-family", "title": "Head – family", "sample": "HFP", "rows": [{"code": "HFP", "meaning": "Self-centering heads for carbon and alloy steel (ISO P) and cast iron (ISO K)"}, {"code": "IFP", "meaning": "Heads for ISO P, ISO M and high temperature alloys (ISO S)"}, {"code": "IFHP", "meaning": "Heads for construction beams and structural steel (DFN ...-BD bodies)"}]}, {"key": "i-dia", "title": "Head – drilling diameter", "sample": "330", "rows": [{"code": "###", "meaning": "Drilling diameter x10 (e.g. 330 = 33.0 mm)"}, {"code": "####", "meaning": "Drilling diameter x100 (e.g. 3334 = 33.34 mm)"}]}, {"key": "i-suffix", "title": "Head – suffix", "sample": "SPADEIQ", "rows": [{"code": "SPADEIQ", "meaning": "SPADE IQ head"}, {"code": "SPADE-BD", "meaning": "SPADE head for construction beams (BD)"}]}, {"key": "t-family", "title": "Drill body – family", "sample": "DFN", "rows": [{"code": "DFN", "meaning": "Exchangeable head drill body with internal coolant holes and a flat shank"}]}, {"key": "t-dia", "title": "Drill body – head size", "rows": [{"code": "###", "meaning": "Smallest head diameter it carries x10 (e.g. 330 = 33.0 mm)"}]}, {"key": "t-length", "title": "Drill body – length", "rows": [{"code": "###", "meaning": "Usable length in mm (inferred)"}]}, {"key": "t-height", "title": "Drill body – shank diameter", "rows": [{"code": "##", "meaning": "Shank diameter in mm (32)"}]}, {"key": "t-shank", "title": "Drill body – shank type", "rows": [{"code": "A", "meaning": "One flat shank"}]}, {"key": "t-depth", "title": "Drill body – drilling depth", "rows": [{"code": "#D", "meaning": "Drilling depth ratio (e.g. 3D = 3xD)"}, {"code": "#.#D", "meaning": "Drilling depth ratio (1.5D = 1.5xD)"}]}, {"key": "t-suffix", "title": "Drill body – suffix", "rows": [{"code": "IQ", "meaning": "IQ line"}, {"code": "BD", "meaning": "Reinforced body for the construction beam industry"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
